import {keyBackground} from './sprite-texture.mjs';
export async function assets(){const a=await loadArt();const im=new Image();im.src='assets/crownlands/class-parts.webp';await im.decode();const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(im,0,0);const p=x.getImageData(0,0,c.width,c.height);keyBackground(p.data,c.width,c.height,4,3);for(let yy=Math.floor(c.height*2/3);yy<c.height;yy++)for(let xx=c.width/2;xx<c.width;xx++){const n=(yy*c.width+xx)*4;if(Math.min(p.data[n],p.data[n+1],p.data[n+2])>235&&Math.max(p.data[n],p.data[n+1],p.data[n+2])-Math.min(p.data[n],p.data[n+1],p.data[n+2])<18)p.data[n+3]=0;}x.putImageData(p,0,0);a.classes=[];const w=c.width/4,h=c.height/3;for(let i=0;i<12;i++){let l=w,t=h,r=0,b=0;for(let yy=0;yy<h;yy++)for(let xx=0;xx<w;xx++)if(p.data[((Math.floor(i/4)*h+yy)*c.width+i%4*w+xx)*4+3]>100){l=Math.min(l,xx);r=Math.max(r,xx);t=Math.min(t,yy);b=Math.max(b,yy);}const out=document.createElement('canvas');out.width=Math.max(1,r-l+1);out.height=Math.max(1,b-t+1);out.getContext('2d').drawImage(c,i%4*w+l,Math.floor(i/4)*h+t,out.width,out.height,0,0,out.width,out.height);a.classes.push(out);}return a;}
export function hero(ctx,art,kind,x,y,gear,opts={}){const {scale=1,time=0,face=1}=opts;if(kind==='dwarf'||kind==='thorn'){ctx.save();if(kind==='thorn')ctx.filter='hue-rotate(38deg)';drawDwarf(ctx,art,x,y,{...opts,boots:gear.boots,weapon:gear.melee>2?2:gear.melee>0?1:0,armor:gear.defense>2?2:gear.defense>0?1:0});ctx.restore();}else{const offset=kind==='mage'?0:4,p=art.classes;ctx.save();ctx.translate(x,y);ctx.scale(face*scale,scale);if(opts.hurt>0)ctx.globalAlpha=.6;const gait=opts.moving?Math.sin(opts.walk||0)*.45:0,bob=Math.sin(time*2)*2;const draw=(i,x,y,w,h)=>ctx.drawImage(opts.marketGear?.starterParts&&i>offset&&i<=offset+3?opts.marketGear.starterParts[i-offset-1]:p[i],x,y,w,h);const limb=opts.marketGear?.starterParts,legImage=limb?.[2]||p[offset+3],armImage=limb?.[1]||p[offset+2];
const armH=76,armW=limb?armH*armImage.width/armImage.height:40;
const drawArm=()=>ctx.drawImage(armImage,-armW*.5,0,armW,armH);
for(const [xx,ang,rear] of [[-17,-gait,true],[13,gait,false]]){
 ctx.save();ctx.translate(xx,rear?-68:-67);ctx.rotate(ang);
 const h=rear?64:67,w=limb?h*legImage.width/legImage.height:50;
 if(rear)ctx.filter='brightness(.88)';
 if(gear.boots>0&&!opts.marketGear?.boots)ctx.filter=`hue-rotate(${gear.boots*18}deg) brightness(${1+gear.boots*.09})`;
 ctx.save();if(opts.marketGear?.boots){ctx.beginPath();ctx.rect(-50,-10,100,34);ctx.clip();}
 ctx.drawImage(legImage,-w*.36,0,w,h);ctx.restore();
 if(opts.marketGear?.boots){const boot=opts.marketGear.bootsParts?.[rear?0:1];const bh=h-19;
  if(boot){const bw=bh*boot.width/boot.height;ctx.save();ctx.scale(-1,1);ctx.drawImage(boot,-bw*.60,h-bh,bw,bh);ctx.restore();}
  else{const im=opts.marketGear.boots,half=im.width/2;ctx.drawImage(im,rear?0:half,0,half,im.height,-18,h-bh,38,bh);}
 }
 ctx.restore();
}ctx.translate(0,-bob);ctx.save();ctx.translate(-36,-143);ctx.rotate(-.1-gait*.45);ctx.scale(-1,1);drawArm();ctx.restore();ctx.save();if(opts.marketGear?.starterParts&&!opts.marketGear?.armor){draw(offset+1,-53,-153,106,110);}else if(opts.marketGear?.baseBody&&!opts.marketGear?.armor){const im=opts.marketGear.baseBody,sx=im.width*.25,sw=im.width*.5;ctx.drawImage(im,sx,0,sw,im.height,-53,-163,106,122);}else{if(gear.defense>0&&!opts.marketGear?.armor)ctx.filter=`brightness(${1+gear.defense*.14}) saturate(${1+gear.defense*.2})`;draw(offset+1,-53,-153,106,110);}if(opts.marketGear?.armor){const im=opts.marketGear.armor,w=112+gear.defense*8;ctx.drawImage(im,-w/2,-155,w,kind==='mage'?158:110);}ctx.restore();if(opts.marketGear?.shoulders){const im=opts.marketGear.shoulders,half=im.width/2;ctx.drawImage(im,0,0,half,im.height,-82,-174,59,57);ctx.drawImage(im,half,0,half,im.height,23,-174,59,57);}if(opts.marketGear?.shield){const im=opts.marketGear.shield,h=72,w=h*im.width/im.height;ctx.save();ctx.translate(-36,-143);ctx.rotate(-.1-gait*.45);ctx.drawImage(im,-w/2,55-h/2,w,h);ctx.restore();}draw(offset,-65,-239,130,130);if(opts.marketGear?.helmet){const im=opts.marketGear.helmet,fit=opts.marketGear.helmetFit||{width:102,heightScale:.76,eyeX:.5,eyeY:.62},w=fit.width,h=w*im.height/im.width*fit.heightScale;ctx.save();ctx.translate(13,kind==="mage"?-181:-177);if(fit.mirror)ctx.scale(-1,1);ctx.drawImage(im,-w*fit.eyeX,-h*fit.eyeY,w,h);ctx.restore();}const angle=opts.armAngle??(opts.fitting?-.60:opts.attack?-.8+Math.sin(opts.attack.t/opts.attack.duration*Math.PI*1.5)*1.7:.1);ctx.save();ctx.translate(36,-143);ctx.rotate(angle);drawArm();ctx.save();ctx.translate(0,65);if(opts.fitting)ctx.rotate(.12-angle);else ctx.rotate(.2);if(opts.marketGear?.weapon)heldItem(ctx,opts.marketGear.weapon,opts.marketGear.weaponTier,opts.fitting,opts.marketGear.weaponGrip);else draw(kind==='mage'?(gear.melee>1?9:8):(Math.max(gear.ranged,gear.melee)>1?11:10),-30,-140,85,175);ctx.restore();if(opts.marketGear?.weapon&&limb){ctx.save();ctx.beginPath();ctx.rect(-armW*.5,armH*.80,armW,armH*.20);ctx.clip();drawArm();ctx.restore();}ctx.restore();ctx.restore();}
 if(gear.magic>0){ctx.save();ctx.strokeStyle=kind==='mage'?'#bb8aff':'#ffe6a0';ctx.lineWidth=2;ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(x+face*45*scale,y-80*scale,7+gear.magic*2,0,Math.PI*2);ctx.stroke();ctx.restore();}}
export function gearImage(art,kind,slot,tier){if(slot==='boots')return kind==='mage'?art.classes[3]:kind==='ranger'?art.classes[7]:art.parts[3];if(slot==='defense')return kind==='mage'?art.classes[1]:kind==='ranger'?art.classes[5]:art.parts[tier>2?8:tier?7:1];if(slot==='magic'){const c=document.createElement('canvas');c.width=100;c.height=120;const x=c.getContext('2d');x.fillStyle=['#b9daef','#a9f7c0','#f4b071','#c3a2ff','#ffe397'][tier];x.font='70px serif';x.textAlign='center';x.fillText('✦',50,83);return c;}if(kind==='mage')return art.classes[tier>1?9:8];if(kind==='ranger')return art.classes[tier>1?11:10];return art.parts[tier>2?6:tier?5:4];}
